begin;
create extension if not exists pgtap with schema extensions;
select extensions.no_plan();
create function pg_temp.candidate(g bigint) returns jsonb language sql as $$
 select jsonb_build_object('markers','[]'::jsonb,'sessions',jsonb_build_array(jsonb_build_object('name','__Host-plannix-s-'||g,'hash',repeat('a',64))));
$$;
create temporary table reset_fixture(g bigint);
insert into reset_fixture values(nextval('private.plannix_auth_generation_seq'));
select extensions.ok(not has_table_privilege('service_role','private.plannix_auth_retired_generations','SELECT,INSERT,UPDATE,DELETE'),'service cannot edit or prune retirement history');
select extensions.ok(not has_table_privilege('authenticated','private.plannix_auth_retired_generations','SELECT,INSERT,UPDATE,DELETE'),'browser cannot access retirement history');
select extensions.ok((select relrowsecurity from pg_class where oid='private.plannix_auth_retired_generations'::regclass),'retirement history has RLS');
select extensions.ok(has_function_privilege('service_role','public.plannix_auth_retire_orphan_generation(jsonb)','EXECUTE'),'service may request retirement');
select extensions.ok(not has_function_privilege('anon','public.plannix_auth_retire_orphan_generation(jsonb)','EXECUTE') and not has_function_privilege('authenticated','public.plannix_auth_retire_orphan_generation(jsonb)','EXECUTE'),'browser roles cannot request retirement');
select extensions.ok(not exists(select 1 from pg_proc p, lateral aclexplode(p.proacl) a where p.oid='public.plannix_auth_retire_orphan_generation(jsonb)'::regprocedure and a.grantee=0),'PUBLIC has no execution grant');
select extensions.is(public.plannix_auth_retire_orphan_generation(null)->>'state','ineligible','null fails closed');
select extensions.is(public.plannix_auth_retire_orphan_generation('[]')->>'state','ineligible','non-object fails closed');
select extensions.is(public.plannix_auth_retire_orphan_generation('{"markers":[],"sessions":[]}')->>'state','ineligible','no orphan is not eligible');
select extensions.is(public.plannix_auth_retire_orphan_generation(jsonb_set(pg_temp.candidate((select g from reset_fixture)),'{markers}','[{}]'))->>'state','ineligible','marker context excluded');
select extensions.is(public.plannix_auth_retire_orphan_generation(jsonb_set(pg_temp.candidate((select g from reset_fixture)),'{sessions,0,name}','"__Host-plannix-r-1"'))->>'state','ineligible','recovery cookie excluded');
select extensions.is(public.plannix_auth_retire_orphan_generation(jsonb_set(pg_temp.candidate((select g from reset_fixture)),'{sessions,0,hash}','"invalid"'))->>'state','ineligible','malformed input excluded');
select extensions.is(public.plannix_auth_retire_orphan_generation(pg_temp.candidate(9999999999999999))->>'state','ineligible','future name cannot be retired');
select extensions.is(public.plannix_auth_retire_orphan_generation(jsonb_set(pg_temp.candidate((select g from reset_fixture)),'{sessions}',jsonb_build_array(pg_temp.candidate(1)->'sessions'->0,pg_temp.candidate(2)->'sessions'->0)))->>'state','ineligible','multiple cookies excluded');
select extensions.is(public.plannix_auth_retire_orphan_generation(pg_temp.candidate((select g from reset_fixture)))->>'state','retired','allocated absent generation can be permanently retired');
select extensions.is(public.plannix_auth_retire_orphan_generation(pg_temp.candidate((select g from reset_fixture)))->>'state','retired','repeat observation is idempotent');
select extensions.is((select count(*) from private.plannix_auth_retired_generations where generation=(select g from reset_fixture)),1::bigint,'single permanent history row');
select extensions.throws_ok($$insert into private.plannix_auth_browser_bindings(generation,marker_hash,expires_at) select g,repeat('a',64),now()+interval '1 day' from reset_fixture$$,'P2010','Authentication generation is retired.','even explicit binding insert cannot reuse retired generation');
insert into auth.users(id,email,email_confirmed_at) values('dd000000-0000-4000-8000-000000000095','retirement@example.test',now());
insert into private.plannix_auth_browser_bindings(marker_hash,expires_at) values(repeat('b',64),now()+interval '1 day');
select extensions.throws_ok($$insert into private.plannix_auth_transitions(binding_id,generation,kind,expires_at) select b.id,f.g,'ordinary',now()+interval '2 minutes' from private.plannix_auth_browser_bindings b,reset_fixture f where b.marker_hash=repeat('b',64)$$,'P2010','Authentication generation is retired.','transition insert cannot reuse retired generation');
select extensions.throws_ok($$insert into private.plannix_auth_sessions(id,binding_id,generation,owner_id,kind,secret_hash,access_envelope,refresh_envelope,expires_at) select gen_random_uuid(),b.id,f.g,'dd000000-0000-4000-8000-000000000095','ordinary',repeat('c',64),'{}','{}',now()+interval '1 day' from private.plannix_auth_browser_bindings b,reset_fixture f where b.marker_hash=repeat('b',64)$$,'P2010','Authentication generation is retired.','session insert cannot reuse retired generation');
select extensions.throws_ok($$update private.plannix_auth_browser_bindings set generation=(select g from reset_fixture) where marker_hash=repeat('b',64)$$,'P2010','Authentication generation is retired.','generation update cannot bypass fence');
select extensions.is(public.plannix_auth_retire_orphan_generation(pg_temp.candidate((select generation from private.plannix_auth_browser_bindings where marker_hash=repeat('b',64))))->>'state','ineligible','existing binding generation excluded');
insert into private.plannix_auth_transitions(binding_id,kind,expires_at) select id,'ordinary',now()+interval '2 minutes' from private.plannix_auth_browser_bindings where marker_hash=repeat('b',64);
select extensions.is(public.plannix_auth_retire_orphan_generation(pg_temp.candidate((select generation from private.plannix_auth_transitions where binding_id=(select id from private.plannix_auth_browser_bindings where marker_hash=repeat('b',64))))) ->>'state','ineligible','reserved generation excluded before session creation');
update private.plannix_auth_transitions set state='failed';
select extensions.is(public.plannix_auth_retire_orphan_generation(pg_temp.candidate((select generation from private.plannix_auth_transitions where binding_id=(select id from private.plannix_auth_browser_bindings where marker_hash=repeat('b',64))))) ->>'state','ineligible','retained failed reservation conservatively excluded');
insert into private.plannix_auth_sessions(id,binding_id,generation,owner_id,kind,secret_hash,access_envelope,refresh_envelope,expires_at) select gen_random_uuid(),id,nextval('private.plannix_auth_generation_seq'),'dd000000-0000-4000-8000-000000000095','ordinary',repeat('c',64),'{}','{}',now()-interval '1 day' from private.plannix_auth_browser_bindings where marker_hash=repeat('b',64);
select extensions.is(public.plannix_auth_retire_orphan_generation(pg_temp.candidate((select generation from private.plannix_auth_sessions where owner_id='dd000000-0000-4000-8000-000000000095')))->>'state','ineligible','even expired existing session is excluded');
select extensions.throws_ok($$update private.plannix_auth_transitions set generation=(select g from reset_fixture)$$,'P2010','Authentication generation is retired.','transition update fenced');
select extensions.throws_ok($$update private.plannix_auth_sessions set generation=(select g from reset_fixture) where owner_id='dd000000-0000-4000-8000-000000000095'$$,'P2010','Authentication generation is retired.','session update fenced');
select extensions.ok(not exists(select 1 from private.plannix_auth_sessions s join private.plannix_auth_retired_generations r using(generation)),'retirement never authenticates or revokes another session');
select extensions.ok((select prosecdef and proconfig @> array['search_path=""','lock_timeout=250ms'] from pg_proc where oid='public.plannix_auth_retire_orphan_generation(jsonb)'::regprocedure),'guard is definer with bounded lock timeout and empty search path');
select extensions.is((select count(*) from pg_trigger where tgname in('plannix_auth_binding_retirement_fence','plannix_auth_transition_retirement_fence','plannix_auth_session_retirement_fence') and tgenabled='O'),3::bigint,'all issuance tables are fenced');
alter sequence private.plannix_auth_generation_seq cache 2;
select extensions.is(public.plannix_auth_retire_orphan_generation(pg_temp.candidate((select g from reset_fixture)))->>'state','unavailable','changed sequence allocation configuration fails closed');
select * from extensions.finish();
rollback;
